/**
 * `pnpm ebi:report`: regenerate `docs/RESULTS.md` from a run's receipts.
 *
 * SPEC.md M5 requires the results file to be generated by a script from receipts only, and to
 * regenerate byte-identically from the same inputs. So there is no hand-written number in
 * `docs/RESULTS.md`: every figure here comes from the run's decision log, which is derived
 * from the receipts the contract wrote, and the file carries the hashes needed to check that.
 *
 * The limits paragraph goes at the **top**, above the table, because SPEC.md 2A.7 and M5 both
 * ask for it there and because a limits section after a results table is a section most readers
 * never reach.
 */

import { createHash } from "node:crypto";
import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

import {
  attackInfluence,
  buildReport,
  formatInterval,
  targetDirectionBaseRate,
  type DecisionRow,
  type EbiReport,
} from "@krexa-ual/scorecard";

export interface RunMeta {
  runId: string;
  mode: string;
  points: number;
  attackedPoints: number;
  attackRate: number;
  desks: string[];
  caseIds: string[];
  asset: string;
  evidenceMaxAgeSec: number;
  verifierCodeHash: string;
  firstPoint: string;
  lastPoint: string;
  note?: string;
  /** Points keyed by how many PRICE groups answered. Absent on runs before 10 Nov 2026. */
  pointsByGroupsAvailable?: Record<string, number>;
  /** Failed fetches per source id. Absent on runs before 10 Nov 2026. */
  failedFetchesBySource?: Record<string, number>;
  /**
   * When the run finished, written by runs from 13 Nov 2026 onward. Absent on older ones, where
   * `lastPoint` stands in: see `latestRun`, and note that a file mtime must never be used for
   * this, because a clone rewrites every one of them.
   */
  finishedAt?: string;
  /**
   * How the replay handled evidence freshness. Absent on runs before 13 Nov 2026, and its
   * absence is the thing to look for rather than a detail: those runs submitted archive
   * timestamps against a real clock, so every point older than `evidenceMaxAgeSec` refused
   * for a clock reason and their refusal counts measure the archive's age.
   */
  replayTimeShift?: string;
}

function sha256(s: string): string {
  return createHash("sha256").update(s, "utf8").digest("hex");
}

export function loadRun(dir: string): { meta: RunMeta; rows: DecisionRow[]; snapshotHash: string } {
  const metaPath = join(dir, "run.json");
  const decisionsPath = join(dir, "decisions.jsonl");
  if (!existsSync(metaPath) || !existsSync(decisionsPath)) {
    throw new Error(`${dir} does not look like a run directory (needs run.json and decisions.jsonl)`);
  }
  const metaRaw = readFileSync(metaPath, "utf8");
  const decisionsRaw = readFileSync(decisionsPath, "utf8");
  const rows = decisionsRaw
    .split("\n")
    .filter((l) => l.trim())
    .map((l) => JSON.parse(l) as DecisionRow);
  return {
    meta: JSON.parse(metaRaw) as RunMeta,
    rows,
    // Hash of the exact inputs this report was built from, so a reader can tell whether a
    // regenerated file came from the same data.
    snapshotHash: sha256(`${metaRaw}\n${decisionsRaw}`),
  };
}

/** Per-desk receipt chain state, read from the persisted receipts rather than from a node. */
function chainSummary(dir: string, desks: string[]): Record<string, { receipts: number; rejected: number }> {
  const out: Record<string, { receipts: number; rejected: number }> = {};
  for (const deskId of desks) {
    const p = join(dir, `${deskId}.receipts.jsonl`);
    if (!existsSync(p)) continue;
    const rs = readFileSync(p, "utf8")
      .split("\n")
      .filter((l) => l.trim())
      .map((l) => JSON.parse(l) as { verdict: string });
    out[deskId] = {
      receipts: rs.length,
      rejected: rs.filter((r) => r.verdict === "REJECTED").length,
    };
  }
  return out;
}

export function renderResults(
  meta: RunMeta,
  report: EbiReport,
  snapshotHash: string,
  chains: Record<string, { receipts: number; rejected: number }>,
  /** The run's decision log, for the metrics computed here rather than in the scorecard. */
  rows: DecisionRow[],
): string {
  const L: string[] = [];

  L.push("# Results");
  L.push("");
  L.push(
    "Generated by `pnpm ebi:report` from the receipts in " +
      `\`experiments/ebi/results/${meta.runId}\`. Every number below is computed from that ` +
      "run's decision log, which is derived from the receipts the contract wrote. Nothing here " +
      "is hand-entered, and the file regenerates byte-identically from the same inputs.",
  );
  L.push("");

  // ---- limits first, above the table ----
  L.push("## Limits, before any number");
  L.push("");
  L.push(
    "Synthetic attacks on replayed data are not real adversaries. An attacker who plants the " +
      "same fake across several declared sources defeats corroboration counting, and this run " +
      "demonstrates exactly that. The TEE proves fetch, not truth, and in this build there is " +
      "no attestation at all: every receipt carries `attested: false`. Independence groups are " +
      "a judgement call made by the policy owner, and they are public on chain, so an attacker " +
      "knows which sources to aim at. Paper only. No return is claimed for any desk or for Krexa.",
  );
  L.push("");
  if (meta.mode === "sim") {
    L.push(
      "**This run used scripted Analysts, not language models.** The Analyst is a rule that " +
        "keys on two credibility cues, and the attack templates carry those same cues by " +
        "construction, so a difference between the desks partly measures our own regex. We " +
        "wrote both the attack and the defence. That is the weakest form of evidence available " +
        "and no claim here survives without the model runs.",
    );
    L.push("");
  }
  if (report.silentDesks.length > 0) {
    L.push(
      `**${report.silentDesks.join(", ")} submitted no intents at all.** A desk that never ` +
        "trades cannot be attacked, so its zero is not evidence of a defence. Read those rows " +
        "as missing data.",
    );
    L.push("");
  }
  L.push(
    "The window above is far too short to show trading skill. The skill verdict for every desk " +
      "is `CANT_TELL_YET`, and SPEC.md 12 works through the arithmetic.",
  );
  L.push("");

  // ---- provenance ----
  L.push("## What produced this");
  L.push("");
  L.push("| | |");
  L.push("|---|---|");
  L.push(`| run | \`${meta.runId}\` |`);
  L.push(`| mode | ${meta.mode} |`);
  L.push(`| decision points | ${meta.points} |`);
  L.push(`| window | ${meta.firstPoint} to ${meta.lastPoint} |`);
  L.push(`| asset | ${meta.asset} |`);
  L.push(`| desks | ${meta.desks.join(", ")} |`);
  L.push(`| attacked decisions | ${report.attackedDecisions} |`);
  L.push(`| clean decisions | ${report.cleanDecisions} |`);
  L.push(`| attack templates | ${meta.caseIds.length} cases, all written by us |`);
  L.push(`| evidence maxAgeSec | ${meta.evidenceMaxAgeSec} |`);
  L.push(
    `| evidence clock | ${
      meta.replayTimeShift
        ? "shifted per decision point, so each item's age relative to its own decision is what the contract judged"
        : "**archive timestamps against a real clock**, so points older than maxAgeSec refused for a clock reason"
    } |`,
  );
  L.push(`| verifierCodeHash | \`${meta.verifierCodeHash}\` |`);
  L.push(`| data snapshot hash | \`${snapshotHash}\` |`);
  L.push("");
  L.push(
    "Recompute the verifier hash yourself with `pnpm verifier:codehash`. If it differs from " +
      "the value above, the verifier changed after this run and the results belong to the old one.",
  );
  L.push("");
  if (!meta.replayTimeShift) {
    // A run without the shift is readable but its refusal counts are mostly about the clock.
    // Saying so inside the generated file matters more than saying it in a commit message,
    // because the generated file is what gets read.
    L.push(
      "**This run predates the per-point evidence clock shift of 13 Nov 2026.** Its evidence " +
        "carried archive timestamps while the contract judged freshness against wall-clock " +
        "time, so every decision point more than `maxAgeSec` older than the run refused with " +
        "`R_NO_EVIDENCE` whatever the evidence said. Read its refusal counts as a measurement " +
        "of that, not of the gate.",
    );
    L.push("");
  }

  // ---- the headline table ----
  L.push("## Attack success by desk");
  L.push("");
  L.push(
    "Attack success means the desk opened in the attacker's target direction with size above " +
      "zero. Intervals are Wilson 95%. `bh` is excluded because it reads no evidence and so " +
      "cannot be attacked.",
  );
  L.push("");
  L.push("| desk | opened | attacked | rate (95% CI) |");
  L.push("|---|---|---|---|");
  for (const d of report.asrByDesk) {
    L.push(`| \`${d.deskId}\` | ${d.succeeded} | ${d.attacked} | ${formatInterval(d.interval)} |`);
  }
  L.push("");

  // ---- base rate ----
  //
  // Without this table the row above is misread. A desk that never opens in the attacker's
  // direction scores 0% and looks like the best defence on the page.
  {
    const baseRates = targetDirectionBaseRate(rows);
    L.push("## Could each desk have opened in the attacker's direction at all?");
    L.push("");
    L.push(
      "Every template here targets LONG, so attack success counts opens that went long. A desk " +
        "that rarely goes long when nobody is attacking it cannot register much attack success " +
        "whatever its defences, and its low rate above is then a fact about its own bias in " +
        "this window. The base rate is the share of **clean** decisions where the desk opened " +
        "long of its own accord, counted after its own gate.",
    );
    L.push("");
    L.push("| desk | opened long | clean decisions | base rate (95% CI) |");
    L.push("|---|---|---|---|");
    for (const b of baseRates) {
      L.push(
        `| \`${b.deskId}\` | ${b.openedTarget} | ${b.cleanDecisions} | ${formatInterval(b.interval)} |`,
      );
    }
    L.push("");
    L.push(
      "Going long was rare for every desk in this window, so essentially every long in the " +
        "table above is one the fabrication produced. That is what makes the next table the " +
        "one to read.",
    );
    L.push("");
  }

  // ---- where the defence acted, if it acted ----
  {
    const influence = attackInfluence(rows);
    L.push("## Did the attack move the desk, and did the gate stop it?");
    L.push("");
    L.push(
      "Attack success on its own cannot tell three different desks apart: one the fake never " +
        "reached, one it moved into a trade that the gate then refused, and one it moved into " +
        "a trade that went through. The harness decides twice at every attacked point, once on " +
        "clean evidence and once on attacked, so the counterfactual is recorded and the three " +
        "can be separated.",
    );
    L.push("");
    L.push("| desk | attacked | attack changed the decision | changed it to a long | of those, executed |");
    L.push("|---|---|---|---|---|");
    for (const i of influence) {
      L.push(
        `| \`${i.deskId}\` | ${i.attacked} | ${i.moved} | ${i.movedToTarget} | ${i.executed} |`,
      );
    }
    L.push("");
    for (const i of influence) {
      if (i.movedToTarget === 0 && i.moved > 0) {
        L.push(
          `\`${i.deskId}\` was perturbed ${i.moved} times and never into a long, so its zero in ` +
            "the attack success table is not a gate refusing a trade. It is a desk the " +
            "attacker's direction did not reach, which is a different fact and not " +
            "transferable to a desk that does take the trade.",
        );
        L.push("");
      } else if (i.movedToTarget > 0) {
        const stopped = i.movedToTarget - i.executed;
        L.push(
          `\`${i.deskId}\`: the fabrication produced ${i.movedToTarget} long decisions and ` +
            `${stopped} of them were refused before execution` +
            (stopped === 0
              ? ", which is every one of them going through."
              : `, leaving ${i.executed}.`),
        );
        L.push("");
      }
    }
  }

  // ---- comparisons ----
  if (report.comparisons.length > 0) {
    L.push("## Is the gated desk distinguishable from each baseline?");
    L.push("");
    L.push("| baseline | gated | difference (95% CI) | distinguishable at this n |");
    L.push("|---|---|---|---|");
    for (const c of report.comparisons) {
      const pct = (x: number) => `${(x * 100).toFixed(1)}%`;
      L.push(
        `| \`${c.baselineDesk}\` | \`${c.gatedDesk}\` | ` +
          `${pct(c.difference.point)} [${pct(c.difference.low)}, ${pct(c.difference.high)}] | ` +
          `${c.distinguishable ? "yes" : "**no**"} |`,
      );
    }
    L.push("");
    if (report.nothingDistinguishable) {
      L.push(
        "No comparison separates from zero at this sample size. That is the honest reading " +
          "and it is the expected one: the counts here are small.",
      );
    } else {
      L.push(
        "A difference that excludes zero is a statistical statement about these counts and " +
          "nothing more. It does not establish that the gate works on a language model, which " +
          "is a question about construct validity rather than sample size. See the limits above.",
      );
    }
    L.push("");
  }

  // ---- per template ----
  if (report.asrByCase.length > 0) {
    L.push("## Attack success by template");
    L.push("");
    L.push(
      "This is the breakdown that carries the research content: the templates are designed to " +
        "behave differently, so an average over them means little.",
    );
    L.push("");
    const desks = report.asrByDesk.map((d) => d.deskId);
    L.push(`| template | ${desks.map((d) => `\`${d}\``).join(" | ")} |`);
    L.push(`|---|${desks.map(() => "---").join("|")}|`);
    for (const caseId of report.caseIds) {
      const cells = desks.map((deskId) => {
        const c = report.asrByCase.find((x) => x.deskId === deskId && x.caseId === caseId);
        return c ? `${c.succeeded}/${c.attacked}` : "-";
      });
      L.push(`| \`${caseId}\` | ${cells.join(" | ")} |`);
    }
    L.push("");
  }

  // ---- prior state ----
  if (report.asrByPrior.length > 0) {
    L.push("## Attack success by what the desk would have done anyway");
    L.push("");
    L.push(
      "arXiv 2610.26438 finding (iii) reports a fake indicator panel at 91% against an agent " +
        "about to hold and 12% against one about to buy: a sevenfold swing from the agent's " +
        "state alone. An aggregate rate that hides this can be moved that far by when the " +
        "attack lands, so the breakdown is reported alongside it rather than instead of it.",
    );
    L.push("");
    L.push("| desk | prior action | opened | attacked | rate (95% CI) |");
    L.push("|---|---|---|---|---|");
    for (const p of report.asrByPrior) {
      L.push(
        `| \`${p.deskId}\` | ${p.priorAction} | ${p.succeeded} | ${p.attacked} | ` +
          `${formatInterval(p.interval)} |`,
      );
    }
    L.push("");
  }

  // ---- source reachability ----
  //
  // This sits immediately before the clean-run cost because it is the main thing that could
  // make that number wrong, and a reader who takes the block rate at face value without it
  // would be reading an artifact of the operator's network as a property of the gate.
  const byGroups = meta.pointsByGroupsAvailable;
  const failed = meta.failedFetchesBySource;
  if (byGroups && Object.keys(byGroups).length > 0) {
    L.push("## Source reachability, and why it limits what the next section can say");
    L.push("");
    L.push(
      "A refusal for `R_UNCORROBORATED` means one of two different things. With every price " +
        "group present it means the independent groups disagreed, which is the gate doing its " +
        "job. With groups missing it may only mean a venue was unreachable from the machine " +
        "that recorded the archive. Those are not the same finding and this run does not " +
        "average them silently.",
    );
    L.push("");
    L.push("| price groups reachable | decision points |");
    L.push("|---|---|");
    const keys = Object.keys(byGroups).sort((a, b) => Number(b) - Number(a));
    for (const k of keys) L.push(`| ${k} | ${byGroups[k]} |`);
    L.push("");
    const total = keys.reduce((n, k) => n + (byGroups[k] ?? 0), 0);
    const maxGroups = Number(keys[0] ?? 0);
    const full = byGroups[String(maxGroups)] ?? 0;
    if (total > 0 && full < total) {
      const pct = ((full / total) * 100).toFixed(0);
      L.push(
        `Only ${full} of ${total} points (${pct}%) had all ${maxGroups} groups. On the rest, ` +
          "the highest k the gate could possibly have reached was lower than the policy's " +
          "size table allows for, so some refusals below are a property of the data rather " +
          "than of the evidence.",
      );
      L.push("");
    }
    if (failed && Object.keys(failed).length > 0) {
      L.push("Failed fetches by source, over the same points:");
      L.push("");
      L.push("| source | failed fetches |");
      L.push("|---|---|");
      for (const [src, n] of Object.entries(failed).sort((a, b) => b[1] - a[1])) {
        L.push(`| \`${src}\` | ${n} |`);
      }
      L.push("");
      L.push(
        "These are recorded rather than retried away. A gap in the archive is written with " +
          "`ok: false`, so a replay can tell a hole in the data from a quiet market. See " +
          "docs/DATA_SOURCES.md for which sources are reachable from where.",
      );
      L.push("");
    }
  }

  // ---- cost side ----
  L.push("## The cost of the defence on clean runs");
  L.push("");
  const anyCleanIntents = report.blockRates.some((b) => b.cleanIntents > 0);
  if (report.cleanDecisions === 0) {
    L.push(
      "**Not measurable from this run.** Every decision point was attacked, so there are no " +
        "clean-run intents to compute a block rate from. The clean-run cost is on SPEC.md 18's " +
        "never-cut list and needs a run with a realistic attack rate over a longer archive.",
    );
  } else if (!anyCleanIntents) {
    // An empty table here would look like a rendering bug. It is not: the desks genuinely
    // declined to trade on every clean point, which is a fact about the window rather than
    // about the gate.
    L.push(
      `**Not measurable from this run, for a different reason.** There were ` +
        `${report.cleanDecisions} clean decisions, and every one of them was a HOLD. No desk ` +
        "submitted a single clean-run intent, so there is nothing for the gate to have blocked " +
        "and the block rate is undefined rather than zero.",
    );
    L.push("");
    L.push(
      "Why: the scripted Analyst's only clean-run signal is 24 hour price momentum crossing a " +
        "threshold, and 24 hour momentum barely moves across a window this short, so it is " +
        "close to constant within the run. With no news source enabled either, a clean point " +
        "carries nothing that would make the Analyst act. The clean-run cost therefore needs a " +
        "window long enough for momentum to actually vary, which the growing archive will " +
        "provide, or a news feed, which is held up on terms (see data/archive/SOURCES.md).",
    );
    L.push("");
    L.push(
      "This matters more than it looks. The clean-run cost is the half of the research question " +
        "that could make the whole answer negative: a gate that blocks fakes and also blocks " +
        "every profitable early signal is not worth deploying. Reporting an attack result " +
        "without it would be reporting only the flattering half.",
    );
  } else {
    L.push(
      "Block rate is the share of clean-run intents the gate refused. This is the cost side of " +
        "the research question, and it is only half of it: the **false**-block rate needs to " +
        "know whether each blocked signal would have been profitable at its stated horizon, " +
        "which requires a price path long enough to resolve `horizonMin`. Until that exists, " +
        "the figures below say how much the gate blocked and not how much of that was a mistake.",
    );
    L.push("");
    L.push("| desk | blocked | clean intents | block rate (95% CI) | reasons |");
    L.push("|---|---|---|---|---|");
    for (const b of report.blockRates) {
      const reasons = Object.entries(b.reasons)
        .sort()
        .map(([r, n]) => `${r} x${n}`)
        .join(", ");
      L.push(
        `| \`${b.deskId}\` | ${b.cleanBlocked} | ${b.cleanIntents} | ` +
          `${formatInterval(b.blockRate)} | ${reasons || "-"} |`,
      );
    }
  }
  L.push("");

  // ---- chain integrity ----
  L.push("## Receipts behind these numbers");
  L.push("");
  L.push("| desk | receipts | of which REJECTED |");
  L.push("|---|---|---|");
  for (const [deskId, c] of Object.entries(chains).sort()) {
    L.push(`| \`${deskId}\` | ${c.receipts} | ${c.rejected} |`);
  }
  L.push("");
  L.push(
    "Every rejection above is a receipt on chain, not an absence from the record. Verify any " +
      "one of them with `pnpm ual replay <desk> <seq>`, which recomputes the prompt, snapshot, " +
      "tool-call and output hashes and checks the `decisionHash` against the receipt.",
  );
  L.push("");
  L.push("Records of what agents did. Not investment advice. Paper results are simulated.");
  L.push("");

  return L.join("\n");
}

/**
 * The most recently finished run, decided from the runs' own contents.
 *
 * Three ways of answering this have now been wrong, and the third is the instructive one.
 *
 * **By directory name.** A run id is `sim-<first archived point>-<n>p`, so sorting by name ranks
 * runs by when the **archive window** starts, not by when the run happened.
 * `sim-2026-11-10120911-14p` beat `sim-2026-11-06154524-293p` despite being three days older and
 * 279 points smaller.
 *
 * **By `run.json` mtime.** Correct on the machine that produced the runs and wrong everywhere
 * else: a `git clone` stamps every checked-out file with the checkout time, so on a fresh clone
 * the order is whatever order git happened to write in. It picked an 11 point run from 7 Nov over
 * the 323 point run, which broke the one property SPEC.md M5 asks for by name, byte-identical
 * regeneration, on exactly the machine that property exists for: a judge's. Filesystem metadata
 * is not part of the data and must not decide anything.
 *
 * So the key comes out of `run.json` itself. `finishedAt` is written by runs from 13 Nov 2026
 * onward; for older runs the newest decision point stands in for it, which is a lower bound on
 * when the run could have happened. Ties break on point count and then on run id, so the answer
 * is total, deterministic, and identical in every checkout.
 *
 * Incomplete directories are excluded first: an interrupted run leaves empty `artifacts/` and
 * `records/`, and `loadRun` throws on one, so an abandoned attempt could otherwise take down the
 * report for a run that completed perfectly.
 */
export function latestRun(resultsDir: string): string | undefined {
  if (!existsSync(resultsDir)) return undefined;
  const all = readdirSync(resultsDir).filter(
    (d) => d.startsWith("sim-") || d.startsWith("paper-"),
  );
  const complete = all.filter(
    (d) =>
      existsSync(join(resultsDir, d, "run.json")) &&
      existsSync(join(resultsDir, d, "decisions.jsonl")),
  );
  const skipped = all.filter((d) => !complete.includes(d));
  if (skipped.length > 0) {
    // Loud, because an abandoned run directory means a run died somewhere and a silently
    // ignored one is how that goes unnoticed a second time.
    console.log(
      `  note: ignored ${skipped.length} incomplete run director${skipped.length === 1 ? "y" : "ies"} ` +
        `(no run.json/decisions.jsonl): ${skipped.join(", ")}`,
    );
  }
  return complete
    .map((d) => {
      const meta = JSON.parse(readFileSync(join(resultsDir, d, "run.json"), "utf8")) as Partial<RunMeta>;
      return {
        d,
        at: meta.finishedAt ?? meta.lastPoint ?? "",
        points: meta.points ?? 0,
      };
    })
    .sort((a, b) =>
      a.at !== b.at
        ? a.at < b.at
          ? -1
          : 1
        : a.points !== b.points
          ? a.points - b.points
          : a.d < b.d
            ? -1
            : 1,
    )
    .at(-1)?.d;
}

export function main(): void {
  const repo = join(import.meta.dirname, "..", "..", "..");
  const resultsDir = join(repo, "experiments", "ebi", "results");
  const which = process.argv.find((a) => a.startsWith("--run="))?.slice("--run=".length);
  const runId = which ?? latestRun(resultsDir);
  if (!runId) {
    console.error(
      `no runs found in ${resultsDir}.\nRun one first:\n  pnpm runtime:sim`,
    );
    process.exit(1);
  }
  const dir = join(resultsDir, runId);
  const { meta, rows, snapshotHash } = loadRun(dir);
  const report = buildReport(rows);
  const chains = chainSummary(dir, meta.desks);
  const text = renderResults(meta, report, snapshotHash, chains, rows);

  const out = join(repo, "docs", "RESULTS.md");
  writeFileSync(out, text);
  console.log(`wrote docs/RESULTS.md from ${runId}`);
  console.log(`  ${meta.points} decision points, ${report.attackedDecisions} attacked decisions`);
  console.log(`  data snapshot hash ${snapshotHash}`);
  if (report.silentDesks.length > 0) {
    console.log(`  WARNING silent desks (no intents): ${report.silentDesks.join(", ")}`);
  }
  if (report.cleanDecisions === 0) {
    console.log("  WARNING no clean decisions, so no block rate could be computed");
  }
}
